function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 1 || stones.length > 1000) return 'stones needs 1 to 1000 points.';
  const seen = new Set();
  for (const point of stones) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each stone is a pair [x, y].';
    const [x, y] = point;
    if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || y < 0 || x > 10000 || y > 10000) return 'Coordinates are whole numbers from 0 to 10^4.';
    const key = x * 10001 + y;
    if (seen.has(key)) return 'No two stones may share the same point.';
    seen.add(key);
  }
  return null;
}

