function removeStones(stones) {
  // Link stones directly when they share a row or column, and count the groups with a depth-first search.
  const n = stones.length;
  const visited = new Array(n).fill(false);
  let groups = 0;
  for (let start = 0; start < n; start++) {
    if (visited[start]) continue;
    groups++;
    visited[start] = true;
    const stack = [start];
    while (stack.length) {
      const i = stack.pop();
      for (let j = 0; j < n; j++) {
        if (!visited[j] && (stones[i][0] === stones[j][0] || stones[i][1] === stones[j][1])) {
          visited[j] = true;
          stack.push(j);
        }
      }
    }
  }
  return n - groups;
}

