function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 600 + pick(401) : 1 + pick(10);
  // The spread decides how crowded the grid is: tiny spreads link most stones, the full spread almost none.
  const spreads = large ? [40, 120, 400, 2000, 10001] : [3, 4, 6, 10, 10001];
  let spread = spreads[pick(spreads.length)];
  while (spread * spread < n) spread++;
  // Offset the used window so stones also appear near the top of the coordinate range.
  const offset = pick(10001 - spread + 1);
  const seen = new Set();
  const stones = [];
  while (stones.length < n) {
    const x = offset + pick(spread);
    const y = offset + pick(spread);
    const key = x * 10001 + y;
    if (seen.has(key)) continue;
    seen.add(key);
    stones.push([x, y]);
  }
  return [stones];
}
